  ('e2000000-0000-4000-a000-000000001842', 'CO-FIS-00769', 6, 527, 'medio', 4, 30, 2026, 'multiple_choice', 'Lançamento oblíquo', 'Uma bola é chutada do chão com velocidade de 10 m/s, formando 30° com a horizontal. Despreze a resistência do ar e use g = 10 m/s², sen 30° ≈ 0,5 e cos 30° ≈ 0,87. Qual é a altura máxima atingida?', 'Componente vertical: vy = 10·0,5 = 5 m/s. Altura máxima: H = vy²/(2g) = 1,3 m. Tempo de subida: vy/g = 0,5 s; tempo total = 1 s.', 'Separe o movimento: na vertical é um lançamento para cima; na horizontal, velocidade constante.', 'Questão autoral da Educa Mais. Referência de estilo: UFPR. Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001843', 'CO-FIS-00770', 6, 527, 'medio', 4, 31, 2026, 'multiple_choice', 'Lançamento oblíquo', 'Uma bola é chutada do chão com velocidade de 30 m/s, formando 45° com a horizontal. Despreze a resistência do ar e use g = 10 m/s², sen 45° ≈ 0,71 e cos 45° ≈ 0,71. Qual é a altura máxima atingida?', 'Componente vertical: vy = 30·0,71 = 21,3 m/s. Altura máxima: H = vy²/(2g) = 22,7 m. Tempo de subida: vy/g = 2,13 s; tempo total = 4,3 s.', 'Separe o movimento: na vertical é um lançamento para cima; na horizontal, velocidade constante.', 'Questão autoral da Educa Mais. Referência de estilo: UFRGS. Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
